    INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1,
                          YMD_TOKEN_COUNT, QTY_TOKEN_COUNT, QTY_NONNULL_COUNT,
                          YMD_STRINGS, QTY_STRINGS, NOTES)
    VALUES (@v_dbg_session_id, SYSDATETIME(), N'ENTRY', N'SP 진입 - 입력 파라미터',
            @P_MEASURE, @P_XLS_KEY1,
            @v_dbg_ymd_cnt, @v_dbg_qty_cnt, @v_dbg_qty_nn_cnt,
            @YMD_STRINGS, @QTY_STRINGS,
            N'P_USER=' + ISNULL(@P_USER_ID,N'') + N', P_DIV=' + ISNULL(@P_DIVISION_ID,N'') +
            N', P_PLAN_START=' + ISNULL(@P_PLAN_START_YYYYMMDD,N'') + N', P_TYPE=' + ISNULL(@P_PLAN_TYPE,N'') +
            N', P_SEQ=' + CAST(ISNULL(@P_SEQ,0) AS NVARCHAR(10)) + N', P_ITEM=' + ISNULL(@P_ITEM_ID,N'') +
            N', P_CREATE_FROM=' + ISNULL(@P_CREATE_FROM_YYYYMMDD,N''));

    BEGIN TRY

        -- 2026-05-15 김준규: 트랜잭션 시작
        --   - SCM_SIM_DYN_COLS UPDATE + SCP_ANL_* MERGE/이력/FIX 처리를 원자적으로 묶음
        --   - 도중 에러 시 모든 변경 ROLLBACK (부분 적용 방지)
        BEGIN TRANSACTION;

        -------------------------------------------------------------------------
        -- PLAN_TYPE / MEASURE 1차 검증
        -------------------------------------------------------------------------
        IF @P_PLAN_TYPE = 'FN'
            RAISERROR(N'PLAN TYPE "FN" CANNOT BE UPDATED', 10, 1);

        IF @P_MEASURE NOT IN ('SHIP_PLAN', 'CELL_PROD')
            RAISERROR(N'PLAN DATA CANNOT BE SAVED WITH REQUESTED MEASURE', 11, 1);

        -------------------------------------------------------------------------
        -- 데이터 행 메타 조회 (SORT_SEQ1 = @v_sort_seq1, BATCH_ID = @v_batch_id)
        --   C1=DIVISION_ID, C2=PLAN_START_YYYYMMDD, C3=CREATE_FROM_YYYYMMDD
        --   C4=PLAN_TYPE,   C5=SEQ,                C6=OPERATION_GROUP(BIZ_TYPE)
        --   C7=FROM_SITE,   C9=CELL_ITEM_ID,       C10=ITEM_ID
        --   C14=MEASURE,    C17=PROJECT_CODE,      C18=TO_SITE
        --   C20=INCOTERMS,  C21=BOD_ID,            C22=TRANSPORT_MODE
        --   C24=PROD_LINE,  C771=ATTRIBUTE1,       C772=ATTRIBUTE3
        --   C773=ATTRIBUTE9(OPERATION_ID),         C774=ATTRIBUTE10
        -------------------------------------------------------------------------
        SELECT TOP 1
               @v_snap_yyyymmdd        = SNAP_YYYYMMDD
              ,@v_report_title         = REPORT_TITLE
              ,@v_plant_id             = PLANT_ID
              ,@v_division_id          = C1
              ,@v_plan_start_yyyymmdd  = C2
              ,@v_create_from_yyyymmdd = C3
              ,@v_plan_type            = C4
              ,@v_seq                  = TRY_CAST(C5 AS INT)
              ,@v_operation_group      = C6
              ,@v_from_site            = C7
              ,@v_cell_item_id         = C9
              ,@v_item_id              = C10
              ,@v_measure              = C14
              ,@v_project_code         = C17
              ,@v_to_site              = C18
              ,@v_incoterms            = C20
              ,@v_bod_id               = C21
              ,@v_transport_mode       = C22
              ,@v_prod_line            = C24
              ,@v_attribute1           = C771
              ,@v_attribute3           = C772
              ,@v_attribute9           = C773
              ,@v_attribute10          = C774
          FROM SCM_SIM_DYN_COLS WITH (NOLOCK)
         WHERE BATCH_ID  = @v_batch_id
           AND SORT_SEQ1 = @v_sort_seq1;

        IF @v_division_id IS NULL
            RAISERROR(N'BATCH_ID/SORT_SEQ1 NOT FOUND IN SCM_SIM_DYN_COLS', 11, 1);

        -- 2026-05-15 김준규: META_LOADED 디버그 로그
        INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1, NOTES)
        VALUES (@v_dbg_session_id, SYSDATETIME(), N'META_LOADED',
                N'SCM_SIM_DYN_COLS 메타 조회 완료', @P_MEASURE, @P_XLS_KEY1,
                N'BATCH_ID=' + CAST(@v_batch_id AS NVARCHAR(20)) + N', SORT_SEQ1=' + CAST(@v_sort_seq1 AS NVARCHAR(10)) +
                N', DIV=' + ISNULL(@v_division_id,N'') + N', PLAN_START=' + ISNULL(@v_plan_start_yyyymmdd,N'') +
                N', TYPE=' + ISNULL(@v_plan_type,N'') + N', SEQ=' + CAST(ISNULL(@v_seq,0) AS NVARCHAR(10)) +
                N', OP_GRP(C6)=' + ISNULL(@v_operation_group,N'') + N', ITEM(C10)=' + ISNULL(@v_item_id,N'') +
                N', MEASURE(C14)=' + ISNULL(@v_measure,N'') + N', ATTR3(C772)=' + ISNULL(@v_attribute3,N'') +
                N', ATTR9(C773)=' + ISNULL(@v_attribute9,N''));

        IF @P_IS_DEBUG = 1
            SELECT @v_division_id        AS DIVISION_ID
                  ,@v_plan_start_yyyymmdd AS PLAN_START_YYYYMMDD
                  ,@v_plan_type           AS PLAN_TYPE
                  ,@v_seq                 AS SEQ
                  ,@v_operation_group     AS OPERATION_GROUP
                  ,@v_item_id             AS ITEM_ID
                  ,@v_cell_item_id        AS CELL_ITEM_ID
                  ,@v_from_site           AS FROM_SITE
                  ,@v_to_site             AS TO_SITE
                  ,@v_measure             AS MEASURE
                  ,@v_bod_id              AS BOD_ID
                  ,@v_attribute3          AS ATTRIBUTE3
                  ,@v_attribute9          AS ATTRIBUTE9;

        -------------------------------------------------------------------------
        -- 입력된 버전과 현재 버전이 다를 경우 EXCEPTION
        -------------------------------------------------------------------------
        IF (@P_DIVISION_ID         <> @v_division_id
         OR @P_PLAN_START_YYYYMMDD <> @v_plan_start_yyyymmdd
         OR @P_PLAN_TYPE           <> @v_plan_type
         OR @P_SEQ                 <> @v_seq)
            RAISERROR(N'PLAN DATA IS DIFFERENT FROM CURRENT PLAN', 11, 1);

        -- 2026-05-15 김준규: AFTER_VALIDATION 디버그 로그
        INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1)
        VALUES (@v_dbg_session_id, SYSDATETIME(), N'AFTER_VALIDATION',
                N'PLAN_TYPE/MEASURE/버전 검증 통과', @P_MEASURE, @P_XLS_KEY1);

        -- ATTRIBUTE3 → BOD from/to 분할 (16자리: LEFT8=from, RIGHT8=to)
        SELECT @v_bod_from = (CASE WHEN @v_attribute3 IS NULL OR LEN(@v_attribute3) < 16 THEN '19900101' ELSE LEFT(@v_attribute3, 8)  END)
              ,@v_bod_to   = (CASE WHEN @v_attribute3 IS NULL OR LEN(@v_attribute3) < 16 THEN '29991231' ELSE RIGHT(@v_attribute3, 8) END);

        -------------------------------------------------------------------------
        -- 변경 데이터셋 : @YMD_STRINGS / @QTY_STRINGS → @CHANGED_DATA
        -------------------------------------------------------------------------
        DECLARE @CHANGED_DATA TABLE (YYYYMMDD VARCHAR(8), QTY NUMERIC(20,10));

        INSERT @CHANGED_DATA (YYYYMMDD, QTY)
        SELECT A.TOKEN, CAST(B.TOKEN AS NUMERIC(20,10))
          FROM STRING_SPLIT(@YMD_STRINGS, ',') A
         INNER JOIN String_Split(@QTY_STRINGS, ',') B
            ON A.NR = B.NR
         WHERE B.TOKEN <> '-9';

        SELECT @v_dbg_rowcnt = COUNT(*) FROM @CHANGED_DATA;

        -- 2026-05-15 김준규: CHANGED_DATA_LOADED 디버그 로그
        INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1,
                              YMD_STRINGS, QTY_STRINGS, YMD_TOKEN_COUNT, QTY_TOKEN_COUNT, ROW_COUNT)
        VALUES (@v_dbg_session_id, SYSDATETIME(), N'CHANGED_DATA_LOADED',
                N'@YMD_STRINGS / @QTY_STRINGS → @CHANGED_DATA 적재 완료',
                @P_MEASURE, @P_XLS_KEY1,
                @YMD_STRINGS, @QTY_STRINGS, @v_dbg_ymd_cnt, @v_dbg_qty_cnt, @v_dbg_rowcnt);

        IF @P_IS_DEBUG = 1
            SELECT '@CHANGED_DATA' AS step, * FROM @CHANGED_DATA;

        -------------------------------------------------------------------------
        -- 2026-06-08 김준규 [YEARBLOCK 대응] 일자 → (블록 물리행 C3, 블록상대 컬럼) 계산 매핑
        --   PSI 가 DATA 를 364일 블록별 '별도 물리행(C3=블록시작일)' 으로 저장 →
        --   변경 일자가 속한 블록을 plan_start 기준 계산하여 해당 물리행(C3)의
        --   블록상대 컬럼(C32~)을 UPDATE. (LABEL3 는 364일까지만 → LABEL3 의존 제거)
        --   RNUM = DATEDIFF(plan_start, 일자)+1 ;  BLK(0-base) = (RNUM-1)/364
        --   C3(블록시작일) = DATEADD(BLK*364, plan_start)
        --   CN = 'C' + (RNUM - BLK*364 + 31)   (예: RNUM 1→C32, RNUM 365→C32)
        --   ※ block1/block2 는 동일 SORT_SEQ1 → C3 로 물리행 구분 (XLS_KEY1 만으로 불가)
        -------------------------------------------------------------------------
        DECLARE @v_blk_size_u   INT  = 364;
        DECLARE @v_plan_start_dt DATE = TRY_CONVERT(DATE, @v_plan_start_yyyymmdd);
        DECLARE @v_set_clause   NVARCHAR(MAX);
        DECLARE @v_blk_c3       NVARCHAR(8);
        DECLARE @v_blk_rowcnt   INT = 0;

        IF @v_plan_start_dt IS NULL
            RAISERROR(N'PLAN_START_YYYYMMDD invalid for YEARBLOCK mapping', 11, 1);

        IF OBJECT_ID('tempdb..#CHG_MAP') IS NOT NULL DROP TABLE #CHG_MAP;
        CREATE TABLE #CHG_MAP (
             YYYYMMDD        VARCHAR(8)
            ,QTY             NUMERIC(20,10)
            ,RNUM            INT
            ,BLK             INT
            ,BLK_CREATE_FROM NVARCHAR(8)
            ,CN_NAME         NVARCHAR(10)
        );

        INSERT INTO #CHG_MAP (YYYYMMDD, QTY, RNUM, BLK, BLK_CREATE_FROM, CN_NAME)
        SELECT C.YYYYMMDD
              ,C.QTY
              ,DATEDIFF(DAY, @v_plan_start_dt, CONVERT(DATE, C.YYYYMMDD)) + 1                                       AS RNUM
              ,(DATEDIFF(DAY, @v_plan_start_dt, CONVERT(DATE, C.YYYYMMDD))) / @v_blk_size_u                         AS BLK
              ,CONVERT(NVARCHAR(8), DATEADD(DAY,
                       ((DATEDIFF(DAY, @v_plan_start_dt, CONVERT(DATE, C.YYYYMMDD))) / @v_blk_size_u) * @v_blk_size_u,
                       @v_plan_start_dt), 112)                                                                     AS BLK_CREATE_FROM
              ,N'C' + CONVERT(NVARCHAR(10),
                       (DATEDIFF(DAY, @v_plan_start_dt, CONVERT(DATE, C.YYYYMMDD)) + 1)
                     - ((DATEDIFF(DAY, @v_plan_start_dt, CONVERT(DATE, C.YYYYMMDD))) / @v_blk_size_u) * @v_blk_size_u
                     + 31)                                                                                         AS CN_NAME
          FROM @CHANGED_DATA C
         WHERE DATEDIFF(DAY, @v_plan_start_dt, CONVERT(DATE, C.YYYYMMDD)) >= 0;  -- plan_start 이전 일자 무시

        SELECT @v_dbg_rowcnt = COUNT(*) FROM #CHG_MAP;
        INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1, ROW_COUNT, NOTES)
        SELECT @v_dbg_session_id, SYSDATETIME(), N'CHG_MAP_BUILT',
               N'변경일자 → 블록/컬럼 계산매핑 완료', @P_MEASURE, @P_XLS_KEY1, @v_dbg_rowcnt,
               N'blocks=' + ISNULL(CAST((SELECT COUNT(DISTINCT BLK_CREATE_FROM) FROM #CHG_MAP) AS NVARCHAR(10)),N'0')
        ;
        IF @P_IS_DEBUG = 1 SELECT '#CHG_MAP' AS step, * FROM #CHG_MAP ORDER BY RNUM;

        -------------------------------------------------------------------------
        -- 블록(C3)별 UPDATE : 변경 일자가 속한 물리행만 SET (블록상대 컬럼)
        --   SCM_SIM_DYN_COLS 컬럼 NVARCHAR(508) → DECIMAL(15,2) 캐스팅 후 N'...' 적재
        -------------------------------------------------------------------------
        IF EXISTS (SELECT 1 FROM #CHG_MAP)
        BEGIN
            DECLARE blk_cur CURSOR LOCAL FAST_FORWARD FOR
                SELECT DISTINCT BLK_CREATE_FROM FROM #CHG_MAP;
            OPEN blk_cur;
            FETCH NEXT FROM blk_cur INTO @v_blk_c3;
            WHILE @@FETCH_STATUS = 0
            BEGIN
                SELECT @v_set_clause = STRING_AGG(
                        CAST(CN_NAME + N' = N''' + CONVERT(NVARCHAR(30), CAST(QTY AS DECIMAL(15,2))) + N'''' AS NVARCHAR(MAX))
                      , N', ')
                  FROM #CHG_MAP
                 WHERE BLK_CREATE_FROM = @v_blk_c3;

                IF @v_set_clause IS NOT NULL AND LEN(@v_set_clause) > 0
                BEGIN
                    SET @SQL = N'
                        UPDATE SCM_SIM_DYN_COLS
                           SET ' + @v_set_clause + N'
                              ,LAST_UPDATED_BY  = @V_USER_ID_sim
                              ,LAST_UPDATE_DATE = GETDATE()
                         WHERE BATCH_ID  = @v_batch_id
                           AND SORT_SEQ1 = @v_sort_seq1
                           AND C3        = @v_blk_c3;';
                    IF @P_IS_DEBUG = 1 BEGIN PRINT N'-- DYNCOLS UPDATE blk C3=' + @v_blk_c3 + N' --'; PRINT LEFT(@SQL, 4000); END
                    EXEC sp_executesql @SQL,
                        N'@v_batch_id BIGINT, @v_sort_seq1 INT, @V_USER_ID_sim NVARCHAR(150), @v_blk_c3 NVARCHAR(8)',
                        @v_batch_id = @v_batch_id, @v_sort_seq1 = @v_sort_seq1,
                        @V_USER_ID_sim = @V_USER_ID_sim, @v_blk_c3 = @v_blk_c3;
                    SET @v_blk_rowcnt = @v_blk_rowcnt + @@ROWCOUNT;
                END
                FETCH NEXT FROM blk_cur INTO @v_blk_c3;
            END
            CLOSE blk_cur; DEALLOCATE blk_cur;

            SET @v_dbg_rowcnt = @v_blk_rowcnt;
            INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1, ROW_COUNT, NOTES)
            VALUES (@v_dbg_session_id, SYSDATETIME(), N'AFTER_DYNCOLS_UPDATE',
                    N'SCM_SIM_DYN_COLS 블록별 동적 UPDATE 완료', @P_MEASURE, @P_XLS_KEY1, @v_dbg_rowcnt,
                    N'BATCH_ID=' + CAST(@v_batch_id AS NVARCHAR(20)) + N', SORT_SEQ1=' + CAST(@v_sort_seq1 AS NVARCHAR(10)) +
                    N', updated_rows=' + CAST(@v_blk_rowcnt AS NVARCHAR(10)));
        END
        ELSE
        BEGIN
            INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1, ROW_COUNT, NOTES)
            VALUES (@v_dbg_session_id, SYSDATETIME(), N'AFTER_DYNCOLS_UPDATE',
                    N'변경 일자(plan_start 이후) 없음 - UPDATE 건너뜀', @P_MEASURE, @P_XLS_KEY1, 0,
                    N'#CHG_MAP 0건');
            IF @P_IS_DEBUG = 1 PRINT N'-- No mappable changed dates : SCM_SIM_DYN_COLS UPDATE skipped';
        END

        -------------------------------------------------------------------------
        -- ★ SHIP_PLAN 분기
        -------------------------------------------------------------------------
        IF @P_MEASURE IN ('SHIP_PLAN')
        BEGIN

            -- 2026-05-15 김준규: SHIP_PLAN_ENTRY 디버그 로그
            INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1, NOTES)
            VALUES (@v_dbg_session_id, SYSDATETIME(), N'SHIP_PLAN_ENTRY',
                    N'SHIP_PLAN 분기 진입 - SCP_ANL_SHIPMENT_PLAN_FG MERGE 시작', @P_MEASURE, @P_XLS_KEY1,
                    N'BOD_FROM=' + ISNULL(@v_bod_from,N'') + N', BOD_TO=' + ISNULL(@v_bod_to,N''));

            IF OBJECT_ID('tempdb..#SCP_ANL_SHIPMENT_PLAN_FG') IS NOT NULL
                DROP TABLE #SCP_ANL_SHIPMENT_PLAN_FG;

            -- 메타(@v_xxx) + @CHANGED_DATA → #SCP_ANL_SHIPMENT_PLAN_FG
            SELECT @v_division_id           AS DIVISION_ID
                  ,@v_plan_start_yyyymmdd   AS PLAN_START_YYYYMMDD
                  ,@v_plan_type             AS PLAN_TYPE
                  ,@v_seq                   AS SEQ
                  ,@v_operation_group       AS BIZ_TYPE
                  ,@v_project_code          AS PROJECT_CODE
                  ,@v_item_id               AS ITEM_ID
                  ,@v_to_site               AS TO_SITE
                  ,@v_incoterms             AS INCOTERMS
                  ,@v_from_site             AS FROM_SITE
                  ,@v_bod_id                AS BOD_ID
                  ,@v_transport_mode        AS TRANSPORT_MODE
                  ,'SHIP_PLAN_AMEND'        AS MEASURE
                  ,Y.YYYYMMDD               AS YYYYMMDD
                  ,Y.QTY                    AS QTY
                  ,@P_DIVISION_ID           AS ORIGIN_FROM_DIVISION_ID
                  ,@P_DIVISION_ID           AS ORIGIN_TO_DIVISION_ID
                  ,''                       AS ELECTRODE_TYPE
                  ,@v_attribute1            AS ATTRIBUTE1
              INTO #SCP_ANL_SHIPMENT_PLAN_FG
              FROM @CHANGED_DATA Y
             WHERE Y.YYYYMMDD BETWEEN @v_bod_from AND @v_bod_to;

            IF @P_IS_DEBUG = 1
                SELECT '#SCP_ANL_SHIPMENT_PLAN_FG' AS step, * FROM #SCP_ANL_SHIPMENT_PLAN_FG;

            -- SCP_ANL_SHIPMENT_PLAN_FG MERGE
            MERGE INTO SCP_ANL_SHIPMENT_PLAN_FG AS X
            USING  #SCP_ANL_SHIPMENT_PLAN_FG AS Y WITH (NOLOCK)
            ON  0 = 0
            AND X.DIVISION_ID         = Y.DIVISION_ID
            AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD
            AND X.PLAN_TYPE           = Y.PLAN_TYPE
            AND X.SEQ                 = Y.SEQ
            AND X.BIZ_TYPE            = Y.BIZ_TYPE
            AND X.PROJECT_CODE        = Y.PROJECT_CODE
            AND X.ITEM_ID             = Y.ITEM_ID
            AND X.TO_SITE             = Y.TO_SITE
            AND X.INCOTERMS           = Y.INCOTERMS
            AND X.FROM_SITE           = Y.FROM_SITE
            AND X.BOD_ID              = Y.BOD_ID
            AND X.MEASURE             = Y.MEASURE
            AND X.YYYYMMDD            = Y.YYYYMMDD
            WHEN MATCHED THEN
                UPDATE
                   SET  X.QTY              = Y.QTY
                       ,X.LAST_UPDATED_BY  = @V_USER_ID_sim
                       ,X.LAST_UPDATE_DATE = GETDATE()
            -- 2026-05-28 김준규: WHEN NOT MATCHED INSERT 제거 — SCP_ANL_SHIPMENT_PLAN_FG 는 UPDATE 만 수행 (신규 INSERT 금지)
            ;

            SET @v_dbg_rowcnt = @@ROWCOUNT;

            -- 2026-05-15 김준규: AFTER_MERGE (SHIP_PLAN) 디버그 로그
            INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1, ROW_COUNT)
            VALUES (@v_dbg_session_id, SYSDATETIME(), N'AFTER_MERGE',
                    N'SCP_ANL_SHIPMENT_PLAN_FG MERGE 완료', @P_MEASURE, @P_XLS_KEY1, @v_dbg_rowcnt);

            -- SCP_ANL_SHIPMENT_PLAN_FG_H : 이력 INSERT
            IF @P_IS_DEBUG = 0
            INSERT INTO dbo.SCP_ANL_SHIPMENT_PLAN_FG_H
            (
                 HISTORY_SEQ, DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ
                ,BIZ_TYPE, PROJECT_CODE, ITEM_ID, TO_SITE, INCOTERMS, FROM_SITE
                ,BOD_ID, MEASURE, YYYYMMDD, QTY
                ,ORIGIN_TO_DIVISION_ID, ORIGIN_FROM_DIVISION_ID, ELECTRODE_TYPE
                ,CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                ,HISTORY_CREATION_DATE
            )
            SELECT
                 NEXT VALUE FOR SEQ1_SCP_ANL_SHIPMENT_PLAN_FG_H
                ,DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ
                ,BIZ_TYPE, PROJECT_CODE, ITEM_ID, TO_SITE, INCOTERMS, FROM_SITE
                ,BOD_ID, MEASURE, YYYYMMDD, QTY
                ,ORIGIN_TO_DIVISION_ID, ORIGIN_FROM_DIVISION_ID, ELECTRODE_TYPE
                ,@V_USER_ID_sim, GETDATE(), @V_USER_ID_sim, GETDATE(), GETDATE()
              FROM #SCP_ANL_SHIPMENT_PLAN_FG WITH (NOLOCK);

            -- SCP_ANL_SHIPMENT_PLAN_FIX : ATTRIBUTE1='Y' marking + QTY 갱신
            IF @P_IS_DEBUG = 0
            UPDATE X
               SET X.QTY              = Y.QTY
                  ,X.FIX_REASON       = 'SIMULATION UPDATE'
                  ,X.ATTRIBUTE1       = 'Y'
                  ,X.LAST_UPDATED_BY  = @V_USER_ID_sim
                  ,X.LAST_UPDATE_DATE = GETDATE()
              FROM SCP_ANL_SHIPMENT_PLAN_FIX X WITH (NOLOCK)
             INNER JOIN #SCP_ANL_SHIPMENT_PLAN_FG Y WITH (NOLOCK)
                ON  0 = 0
               AND X.DIVISION_ID  = Y.DIVISION_ID
               AND X.BIZ_TYPE     = Y.BIZ_TYPE
               AND X.PROJECT_CODE = Y.PROJECT_CODE
               AND X.ITEM_ID      = Y.ITEM_ID
               AND X.TO_SITE      = Y.TO_SITE
               AND X.FROM_SITE    = Y.FROM_SITE
               AND X.BOD_ID       = Y.BOD_ID
               AND X.YYYYMMDD     = Y.YYYYMMDD;

            -- SCP_ANL_SHIPMENT_PLAN_FIX_H : FIX 이력 INSERT
            IF @P_IS_DEBUG = 0
            INSERT INTO dbo.SCP_ANL_SHIPMENT_PLAN_FIX_H
            (
                 HISTORY_SEQ, FIX_ID, DIVISION_ID, BIZ_TYPE
                ,ITEM_ID, TO_SITE, FROM_SITE, PROJECT_CODE, INCOTERMS, BOD_ID
                ,YYYYMMDD, QTY, FIX_REASON
                ,ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, ELECTRODE_TYPE
                ,CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                ,HISTORY_CREATION_DATE
            )
            SELECT NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H
                  ,FIX_ID, DIVISION_ID, BIZ_TYPE
                  ,ITEM_ID, TO_SITE, FROM_SITE, PROJECT_CODE, INCOTERMS, BOD_ID
                  ,YYYYMMDD, QTY, FIX_REASON
                  ,ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, ELECTRODE_TYPE
                  ,@V_USER_ID_sim, GETDATE(), @V_USER_ID_sim, GETDATE(), GETDATE()
              FROM SCP_ANL_SHIPMENT_PLAN_FIX WITH (NOLOCK)
             WHERE ATTRIBUTE1 = N'Y';

            -- SCP_ANL_SHIPMENT_PLAN_FIX : ATTRIBUTE1 NULL 복구
            IF @P_IS_DEBUG = 0
            UPDATE X
               SET X.ATTRIBUTE1 = NULL
              FROM SCP_ANL_SHIPMENT_PLAN_FIX X WITH (NOLOCK)
             INNER JOIN #SCP_ANL_SHIPMENT_PLAN_FG Y WITH (NOLOCK)
                ON  0 = 0
               AND X.DIVISION_ID  = Y.DIVISION_ID
               AND X.BIZ_TYPE     = Y.BIZ_TYPE
               AND X.PROJECT_CODE = Y.PROJECT_CODE
               AND X.ITEM_ID      = Y.ITEM_ID
               AND X.TO_SITE      = Y.TO_SITE
               AND X.FROM_SITE    = Y.FROM_SITE
               AND X.BOD_ID       = Y.BOD_ID
               AND X.YYYYMMDD     = Y.YYYYMMDD
               AND X.ATTRIBUTE1   = N'Y';

        END  -- SHIP_PLAN 종료

        -------------------------------------------------------------------------
        -- ★ CELL_PROD 분기
        -------------------------------------------------------------------------
        IF @P_MEASURE IN ('CELL_PROD')
        BEGIN

            -- 2026-05-15 김준규: CELL_PROD_ENTRY 디버그 로그
            INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1, NOTES)
            VALUES (@v_dbg_session_id, SYSDATETIME(), N'CELL_PROD_ENTRY',
                    N'CELL_PROD 분기 진입 - SCP_ANL_PRODUCTION_PLAN MERGE 시작', @P_MEASURE, @P_XLS_KEY1,
                    N'LINE_ID=' + ISNULL(@v_prod_line,N'') + N', OP_ID(C773)=' + ISNULL(@v_attribute9,N''));

            IF OBJECT_ID('tempdb..#SCP_ANL_PRODUCTION_PLAN') IS NOT NULL
                DROP TABLE #SCP_ANL_PRODUCTION_PLAN;

            -- 메타(@v_xxx) + @CHANGED_DATA → #SCP_ANL_PRODUCTION_PLAN
            SELECT @v_division_id          AS DIVISION_ID
                  ,@v_plan_start_yyyymmdd  AS PLAN_START_YYYYMMDD
                  ,@v_plan_type            AS PLAN_TYPE
                  ,@v_seq                  AS SEQ
                  ,CONVERT(NVARCHAR(10), 'A') AS OPERATION_GROUP
                  ,@v_from_site            AS SCM_SITE_ID
                  ,@v_item_id              AS ITEM_ID
                  ,@v_prod_line            AS LINE_ID
                  ,@v_attribute9           AS OPERATION_ID
                  ,'PROD_PLAN_AMEND'       AS MEASURE
                  ,Y.YYYYMMDD              AS YYYYMMDD
                  ,Y.QTY                   AS QTY
                  ,@v_division_id          AS ORIGIN_DIVISION_ID
                  ,''                      AS ELECTRODE_TYPE
                  ,'0'                     AS CELL_QTY
              INTO #SCP_ANL_PRODUCTION_PLAN
              FROM @CHANGED_DATA Y;

            IF @P_IS_DEBUG = 1
                SELECT '#SCP_ANL_PRODUCTION_PLAN' AS step, * FROM #SCP_ANL_PRODUCTION_PLAN;

            -- 2026-05-28 김준규: INSERT...SELECT FROM(MERGE...OUTPUT) 래퍼 제거.
            --   기존: PROD_PLAN_AMEND MERGE(UPDATE/INSERT) + 신규 INSERT 행에 대한 PROD_PLAN_ENGINE 동반 INSERT
            --   변경: SCP_ANL_PRODUCTION_PLAN 은 UPDATE 만 수행 (신규 INSERT 금지) → WHEN NOT MATCHED / OUTPUT / 동반 INSERT 전부 삭제
                MERGE INTO SCP_ANL_PRODUCTION_PLAN AS X
                USING (SELECT DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ
                             ,OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID
                             ,MEASURE, YYYYMMDD, QTY
                             ,ORIGIN_DIVISION_ID, ELECTRODE_TYPE, CELL_QTY
                         FROM #SCP_ANL_PRODUCTION_PLAN
                      ) AS Y
                ON  0 = 0
                AND X.DIVISION_ID         = Y.DIVISION_ID
                AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD
                AND X.PLAN_TYPE           = Y.PLAN_TYPE
                AND X.SEQ                 = Y.SEQ
                AND X.OPERATION_GROUP     = Y.OPERATION_GROUP
                AND X.SCM_SITE_ID         = Y.SCM_SITE_ID
                AND X.ITEM_ID             = Y.ITEM_ID
                AND X.MEASURE             = Y.MEASURE
                AND X.YYYYMMDD            = Y.YYYYMMDD
                AND X.LINE_ID             = Y.LINE_ID
                AND X.OPERATION_ID        = Y.OPERATION_ID
                AND X.ORIGIN_DIVISION_ID  = Y.ORIGIN_DIVISION_ID
                AND X.ELECTRODE_TYPE      = Y.ELECTRODE_TYPE
                WHEN MATCHED THEN
                    UPDATE
                       SET X.QTY              = Y.QTY
                          ,X.LAST_UPDATED_BY  = @V_USER_ID_sim
                          ,X.LAST_UPDATE_DATE = GETDATE()
            ;

            SET @v_dbg_rowcnt = @@ROWCOUNT;

            -- 2026-05-15 김준규: AFTER_MERGE (CELL_PROD) 디버그 로그
            INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1, ROW_COUNT)
            VALUES (@v_dbg_session_id, SYSDATETIME(), N'AFTER_MERGE',
                    N'SCP_ANL_PRODUCTION_PLAN MERGE 완료', @P_MEASURE, @P_XLS_KEY1, @v_dbg_rowcnt);

            -- SCP_ANL_PRODUCTION_PLAN_H : 이력 INSERT
            IF @P_IS_DEBUG = 0
            INSERT INTO dbo.SCP_ANL_PRODUCTION_PLAN_H
            (
                 HISTORY_SEQ, DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ
                ,OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID
                ,MEASURE, YYYYMMDD, QTY
                ,ORIGIN_DIVISION_ID, ELECTRODE_TYPE
                ,CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                ,HISTORY_CREATION_DATE
            )
            SELECT NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_H
                  ,DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ
                  ,OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID
                  ,MEASURE, YYYYMMDD, QTY
                  ,ORIGIN_DIVISION_ID, ELECTRODE_TYPE
                  ,@V_USER_ID_sim, GETDATE(), @V_USER_ID_sim, GETDATE(), GETDATE()
              FROM #SCP_ANL_PRODUCTION_PLAN WITH (NOLOCK);

            -- SCP_ANL_PRODUCTION_PLAN_FIX : ATTRIBUTE1='Y' marking + QTY 갱신
            IF @P_IS_DEBUG = 0
            UPDATE X
               SET X.QTY              = Y.QTY
                  ,X.ATTRIBUTE1       = 'Y'
                  ,X.LAST_UPDATED_BY  = @V_USER_ID_sim
                  ,X.LAST_UPDATE_DATE = GETDATE()
              FROM SCP_ANL_PRODUCTION_PLAN_FIX X WITH (NOLOCK)
             INNER JOIN #SCP_ANL_PRODUCTION_PLAN Y WITH (NOLOCK)
                ON  0 = 0
               AND X.DIVISION_ID     = Y.DIVISION_ID
               AND X.OPERATION_GROUP = Y.OPERATION_GROUP
               AND X.SCM_SITE_ID     = Y.SCM_SITE_ID
               AND X.ITEM_ID         = Y.ITEM_ID
               AND X.LINE_ID         = Y.LINE_ID
               AND X.OPERATION_ID    = Y.OPERATION_ID
               AND X.YYYYMMDD        = Y.YYYYMMDD;

            -- SCP_ANL_PRODUCTION_PLAN_FIX_H : FIX 이력 INSERT
            IF @P_IS_DEBUG = 0
            INSERT INTO dbo.SCP_ANL_PRODUCTION_PLAN_FIX_H
            (
                 HISTORY_SEQ, FIX_ID
                ,DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID
                ,YYYYMMDD, QTY, FIX_REASON
                ,ORIGIN_DIVISION_ID, ELECTRODE_TYPE
                ,CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                ,HISTORY_CREATION_DATE
            )
            SELECT NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H
                  ,FIX_ID
                  ,DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID
                  ,YYYYMMDD, QTY, FIX_REASON
                  ,ORIGIN_DIVISION_ID, ELECTRODE_TYPE
                  ,@V_USER_ID_sim, GETDATE(), @V_USER_ID_sim, GETDATE(), GETDATE()
              FROM SCP_ANL_PRODUCTION_PLAN_FIX WITH (NOLOCK)
             WHERE ATTRIBUTE1 = 'Y';

            -- SCP_ANL_PRODUCTION_PLAN_FIX : ATTRIBUTE1 NULL 복구
            IF @P_IS_DEBUG = 0
            UPDATE X
               SET X.ATTRIBUTE1 = NULL
              FROM SCP_ANL_PRODUCTION_PLAN_FIX X WITH (NOLOCK)
             INNER JOIN #SCP_ANL_PRODUCTION_PLAN Y WITH (NOLOCK)
                ON  0 = 0
               AND X.DIVISION_ID     = Y.DIVISION_ID
               AND X.OPERATION_GROUP = Y.OPERATION_GROUP
               AND X.SCM_SITE_ID     = Y.SCM_SITE_ID
               AND X.ITEM_ID         = Y.ITEM_ID
               AND X.LINE_ID         = Y.LINE_ID
               AND X.OPERATION_ID    = Y.OPERATION_ID
               AND X.YYYYMMDD        = Y.YYYYMMDD
               AND X.ATTRIBUTE1      = N'Y';

        END  -- CELL_PROD 종료

        -----------------------------------------------------------
        -- 실행 Logic END --
        -----------------------------------------------------------
        SELECT @v_log_message = N'UPDATE INTO ' + @v_table_id,
               @d_event_date  = SYSDATETIME();
        IF @P_IS_DEBUG = 0
            EXEC PR_SCP_SYS_LOG_BATCH @v_program_name, 'TXN', @@ROWCOUNT, @v_log_message, @v_description, @d_event_date, @P_USER_ID;

        -- 2026-05-15 김준규: 트랜잭션 COMMIT (모든 변경 정상 반영)
        IF @@TRANCOUNT > 0
            COMMIT TRANSACTION;

        -- 2026-05-15 김준규: EXIT 디버그 로그
        INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1)
        VALUES (@v_dbg_session_id, SYSDATETIME(), N'EXIT', N'SP 정상 종료 (COMMIT)', @P_MEASURE, @P_XLS_KEY1);

        -- 2026-05-15 김준규: DEBUG = 1 일 때 누적된 로그 결과셋 자동 DISPLAY
        IF @P_IS_DEBUG = 1
            SELECT DBG_ID, STEP, CALL_TIME, MESSAGE, P_MEASURE, P_XLS_KEY1
                  ,YMD_TOKEN_COUNT, QTY_TOKEN_COUNT, QTY_NONNULL_COUNT
                  ,YMD_STRINGS, QTY_STRINGS, NOTES, ROW_COUNT
                  ,ERROR_NUMBER, ERROR_MESSAGE, ERROR_LINE
              FROM @DBG_LOG
             ORDER BY DBG_ID;

    END TRY

    BEGIN CATCH
        -- 2026-05-15 김준규: 트랜잭션 ROLLBACK (에러 발생 시 모든 변경 취소)
        --   - @@TRANCOUNT > 0 체크: XACT_ABORT 로 이미 ROLLBACK 된 경우 중복 방지
        --   - @DBG_LOG 는 테이블 변수라 ROLLBACK 영향 없음 → 모든 단계 로그 보존
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        -- 2026-05-15 김준규: CATCH 디버그 로그
        INSERT INTO @DBG_LOG (SESSION_ID, CALL_TIME, STEP, MESSAGE, P_MEASURE, P_XLS_KEY1,
                              ERROR_NUMBER, ERROR_MESSAGE, ERROR_LINE)
        VALUES (@v_dbg_session_id, SYSDATETIME(), N'CATCH', N'에러 발생 - 트랜잭션 ROLLBACK',
                @P_MEASURE, @P_XLS_KEY1,
                ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE());

        SELECT @v_log_message = CAST(ERROR_MESSAGE() AS NVARCHAR(1000)),
               @v_description = N'ERROR_LINE : ' + STR(ERROR_LINE()),
               @d_event_date  = SYSDATETIME();
        IF @P_IS_DEBUG = 0
            EXEC PR_SCP_SYS_LOG_BATCH @v_program_name, 'ERROR', @@ROWCOUNT, @v_log_message, @v_description, @d_event_date, @P_USER_ID;

        -- 2026-05-15 김준규: DEBUG = 1 일 때 누적된 로그 결과셋 자동 DISPLAY (에러 위치 확인)
        IF @P_IS_DEBUG = 1
            SELECT DBG_ID, STEP, CALL_TIME, MESSAGE, P_MEASURE, P_XLS_KEY1
                  ,YMD_TOKEN_COUNT, QTY_TOKEN_COUNT, QTY_NONNULL_COUNT
                  ,YMD_STRINGS, QTY_STRINGS, NOTES, ROW_COUNT
                  ,ERROR_NUMBER, ERROR_MESSAGE, ERROR_LINE
              FROM @DBG_LOG
             ORDER BY DBG_ID;

        -- 2026-05-15 김준규: 에러를 호출자에게 재발생 (클라이언트가 실패 인지)
        THROW;
    END CATCH;

    -- 실행시간 측정
    SET @v_exec_time =  REPLICATE('0', 2 - LEN((CONVERT(VARCHAR, (DATEDIFF(SECOND, @v_start_time, SYSDATETIME()) / 60))))) + (CONVERT(VARCHAR, (DATEDIFF(SECOND, @v_start_time, SYSDATETIME()) / 60))) + ':' +
                        REPLICATE('0', 2 - LEN((CONVERT(VARCHAR, (DATEDIFF(SECOND, @v_start_time, SYSDATETIME()) % 60))))) + (CONVERT(VARCHAR, (DATEDIFF(SECOND, @v_start_time, SYSDATETIME()) % 60)));

    -- 종료 LOG
    SELECT @v_log_message = N'########## END of procedure ##########',
           @d_event_date  = SYSDATETIME(),
           @v_description = N'[' + @P_DIVISION_ID + '][' + @P_PLAN_START_YYYYMMDD + '][' + @P_MEASURE + '][' + @P_XLS_KEY1 + '][' + @v_exec_time + ']';
    IF @P_IS_DEBUG = 0
        EXEC PR_SCP_SYS_LOG_BATCH @v_program_name, 'END', @@ROWCOUNT, @v_log_message, @v_description, @d_event_date, @P_USER_ID;

    RETURN 0;

END; --BODY
